module seq_detect_1011_mealy(
    input       clk,
    input       rst_n,
    input       bit_in,
    output reg  hit
);
    localparam S_IDLE = 2'd0, S_ONE = 2'd1, S_TEN = 2'd2, S_ONEZEROONE = 2'd3;
    reg [1:0] state;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE;
            hit   <= 1'b0;
        end else begin
            case (state)
                S_IDLE:       state <= bit_in ? S_ONE : S_IDLE;
                S_ONE:        state <= bit_in ? S_ONE : S_TEN;
                S_TEN:        state <= bit_in ? S_ONEZEROONE : S_IDLE;
                S_ONEZEROONE: state <= bit_in ? S_ONE : S_TEN;
                default:      state <= S_IDLE;
            endcase
            // TODO: assert hit on the row the final 1 of 1011 arrives
        end
    end
endmodule

module fifo_flag_fix_8x4(
    input       clk,
    input       rst_n,
    input       wr,
    input       rd,
    input [7:0] wdata,
    output      full,
    output      empty,
    output [2:0] count,
    output [7:0] rdata
);
    reg [7:0] mem [0:3];
    reg [1:0] head, tail;
    reg [2:0] cnt;

    // BUG: full fires one entry early; the depth is 4
    assign full   = (cnt == 3'd3);
    assign empty  = (cnt == 3'd0);
    assign count  = cnt;
    assign rdata  = (cnt != 3'd0) ? mem[head] : 8'd0;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            head <= 2'd0;
            tail <= 2'd0;
            cnt  <= 3'd0;
        end else begin
            if (wr && !full) begin
                mem[tail] <= wdata;
                tail <= tail + 2'd1;
            end
            if (rd && !empty) begin
                head <= head + 2'd1;
            end
            case ({wr && !full, rd && !empty})
                2'b10:   cnt <= cnt + 3'd1;
                2'b01:   cnt <= cnt - 3'd1;
                default: cnt <= cnt;
            endcase
        end
    end
endmodule

