module seq_detect_1101_fix(
    input       clk,
    input       rst_n,
    input       bit_in,
    output reg  hit
);
    localparam S_A = 2'd0, S_B = 2'd1, S_C = 2'd2, S_D = 2'd3;
    reg [1:0] state, next_state;

    always @(*) begin
        case (state)
            S_A: next_state = bit_in ? S_B : S_A;
            S_B: next_state = bit_in ? S_C : S_A;
            S_C: next_state = bit_in ? S_C : S_D;
            S_D: next_state = bit_in ? S_B : S_A;
            default: next_state = S_A;
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_A;
            hit   <= 1'b0;
        end else begin
            state <= next_state;
            hit   <= (next_state == S_D);  // BUG: one cycle early, and the final bit is not qualified
        end
    end
endmodule

