module uart_tx_stop_fix(
    input       clk,
    input       rst_n,
    input       start,
    input [7:0] data,
    output reg  tx,
    output reg  busy
);
    localparam S_IDLE = 2'd0, S_START = 2'd1, S_DATA = 2'd2;
    reg [1:0] state;
    reg [2:0] bit_idx;
    reg [7:0] shreg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state   <= S_IDLE;
            bit_idx <= 3'd0;
            shreg   <= 8'd0;
            tx      <= 1'b1;
            busy    <= 1'b0;
        end else begin
            case (state)
                S_IDLE: begin
                    if (start) begin
                        shreg <= data;
                        tx    <= 1'b0;
                        busy  <= 1'b1;
                        state <= S_START;
                    end
                end
                S_START: begin
                    tx    <= shreg[0];
                    state <= S_DATA;
                end
                S_DATA: begin
                    // BUG: after the eighth data bit the machine falls back to idle
                    if (bit_idx == 3'd7) begin
                        state   <= S_IDLE;
                        busy    <= 1'b0;
                        bit_idx <= 3'd0;
                    end else begin
                        tx      <= shreg[bit_idx + 3'd1];
                        bit_idx <= bit_idx + 3'd1;
                    end
                end
                default: state <= S_IDLE;
            endcase
        end
    end
endmodule

