module arbiter_grant_hold_fix(
    input       clk,
    input       rst_n,
    input [3:0] req,
    output [3:0] grant
);
    reg [3:0] grant_r;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            grant_r <= 4'b0000;
        end else begin
            // BUG: re-arbitrates every cycle, so a higher-priority request
            // steals the grant from a requester that is still asserting req
            if (req[3])      grant_r <= 4'b1000;
            else if (req[2]) grant_r <= 4'b0100;
            else if (req[1]) grant_r <= 4'b0010;
            else if (req[0]) grant_r <= 4'b0001;
            else             grant_r <= 4'b0000;
        end
    end

    assign grant = grant_r;
endmodule

